import React, {useEffect, useState, useCallback} from 'react';
import axios from 'axios';
import './App.css';
function App() { 

  const [city, setCity] = useState('');
  const [weatherData, setWeatherData]= useState(null);
  const fetchData = useCallback( async ()=>{
    try{
        const response = await axios.get(`https://api.weathermap.org/data/2.5/weather?${city}&units=metric&appid=a8eb5aa64568880f32d4b8f8d32e1a9d`);
        setWeatherData(response.data)
        console.log(response.data)
    }
    catch(error){
      console.error(error);
    }
  }, [city])

  useEffect(()=>{
    fetchData();
  }, [fetchData])


  const handleInputChange=(e)=>{
    setCity(e.target.value);
  };

  const handleSubmit=(e) =>{
    e.preventDefault();
    fetchData();
  };

  return (
    <div>
    <form onSubmit={handleSubmit}>
      <input type="text" placeholder="Enter City name" value={city} onChange={handleInputChange}/>

      <button type="submit">Get Weather</button>
    </form>

    {weatherData ? (
      <>
      <h2>{weatherData.name}</h2>
      <p>Temperature: {weatherData.main.temp} </p>
      <p> Description: {weatherData.weather[0].description}</p>
      <p> Wind Speed: {weatherData.wind.speed} m/s</p>
      </>
    ) : (
      <p> Loading weather data...</p>
    )}
    </div>
  );
}

export default App;
